syntax = "proto3";
package orders.v1;

service OrderService {
  rpc GetOrder(GetOrderRequest) returns (GetOrderResponse);
  rpc WatchOrders(WatchOrdersRequest) returns (stream OrderEvent);
  rpc ReportTelemetry(stream TelemetryPoint) returns (ReportSummary);
}

message GetOrderRequest { string order_id = 1; }
message GetOrderResponse { string order_id = 1; int64 total_cents = 2; }
message WatchOrdersRequest { string customer_id = 1; }
message OrderEvent { string order_id = 1; string status = 2; }
message TelemetryPoint { string device_id = 1; double temp_c = 2; }
message ReportSummary { int64 accepted = 1; }

import grpc
from concurrent import futures
import orders_pb2, orders_pb2_grpc

class Orders(orders_pb2_grpc.OrderServiceServicer):
    def GetOrder(self, request, context):
        # Deadline and metadata are first-class: read them, enforce them.
        md = dict(context.invocation_metadata())
        if context.is_active() is False:
            context.set_code(grpc.StatusCode.CANCELLED)
            return orders_pb2.GetOrderResponse()
        return orders_pb2.GetOrderResponse(order_id=request.order_id, total_cents=999)

    def WatchOrders(self, request, context):
        # Server streaming: respect cancellation or you leak a goroutine/thread per watcher.
        for i in range(1000):
            if not context.is_active():
                break
            yield orders_pb2.OrderEvent(order_id=str(i), status="SHIPPED")

server = grpc.server(futures.ThreadPoolExecutor(max_workers=32),
    options=[("grpc.max_receive_message_length", 8 * 1024 * 1024)])
orders_pb2_grpc.add_OrderServiceServicer_to_server(Orders(), server)
server.add_insecure_port("[::]:50051")
server.start()
server.wait_for_termination()
